from taf.ue.tm500.asc.command.versions import v0_0_0
# import classes in v0_0_0 is required to make them visible when import v1_13_0


class ShowGroups(v0_0_0.ShowGroups):
    def _parse_output(self, content):
        """
        content example:
        'showgroups\r\nGroups:\r\n  prod test                       prodtest
        .....U 0 0000 0000 000_001 1 Off\r\n  AllUnits                        tm500'
        .LP... 0 0000 0000 01F_001 13 On \r\n\x1b]2;ascconsole\x07\rASC> \x1b[J'
        """
        lines = self._split_lines(content)
        groups = []
        for line in lines:
            if line.endswith('On') or line.endswith('Off'):
                attributes = self._split_columns(line)
                groups.append(tuple(attributes))
        return groups
